<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin']);$pdo=db();if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)$_POST['id'];$st=$pdo->prepare('UPDATE social_links SET platform=?,url=?,is_active=?,sort_order=? WHERE id=?');$st->execute([trim($_POST['platform']??''),trim($_POST['url']??''),(int)isset($_POST['is_active']),(int)($_POST['sort_order']??0),$id]);log_admin("Updated social link #$id");flash('admin_success','Social link saved.');}if($a==='add'){$st=$pdo->prepare('INSERT INTO social_links(platform,url,is_active,sort_order) VALUES(?,?,?,?)');$st->execute([trim($_POST['platform']??''),trim($_POST['url']??''),1,(int)($_POST['sort_order']??0)]);log_admin('Added social link');flash('admin_success','Social link added.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM social_links WHERE id=?')->execute([$id]);log_admin("Deleted social link #$id");flash('admin_success','Social link deleted.');}}catch(Throwable $e){flash('admin_error','Social link error: '.$e->getMessage());}redirect('admin/social.php');}$rows=$pdo->query('SELECT * FROM social_links ORDER BY sort_order,id')->fetchAll();admin_page('Social Links','social','Edit the social buttons shown on the website.');admin_flash();?><div class="admin-panel"><h2>Add Social Link</h2><form class="admin-form"><!-- disabled display; actual form below --></form><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="admin-form-grid three"><label>Platform<input name="platform" placeholder="Telegram" required></label><label>URL<input name="url" placeholder="https://t.me/wcudc" required></label><label>Order<input type="number" name="sort_order" value="0"></label></div><button class="btn primary">Add Link</button></form></div><div class="admin-panel"><h2>Social Accounts</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Platform</th><th>URL</th><th>Active</th><th>Order</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><form method="post"><td><input name="platform" value="<?=e($r['platform'])?>"></td><td><input name="url" value="<?=e($r['url'])?>"></td><td><input type="checkbox" name="is_active" <?=!empty($r['is_active'])?'checked':''?>></td><td><input type="number" name="sort_order" value="<?=e((string)$r['sort_order'])?>" style="width:70px"></td><td><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small outline">Save</button></form> <form style="display:inline" method="post" onsubmit="return confirm('Delete social link?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
